```javascript
function alignReplies(requestIds, replies) {
  if (!Array.isArray(requestIds) || !Array.isArray(replies)) throw new TypeError('Expected arrays');
  if (requestIds.some((id) => typeof id !== 'string' || id.length === 0) || new Set(requestIds).size !== requestIds.length) {
    throw new TypeError('Invalid request IDs');
  }
  const seen = new Set();
  for (const reply of replies) {
    if (reply === null || typeof reply !== 'object' || Array.isArray(reply) ||
        Object.keys(reply).length !== 2 || !Object.prototype.hasOwnProperty.call(reply, 'requestId') ||
        !Object.prototype.hasOwnProperty.call(reply, 'payload') || typeof reply.requestId !== 'string' ||
        reply.requestId.length === 0 || seen.has(reply.requestId)) throw new TypeError('Invalid reply');
    const payloadValid = reply.payload === null || typeof reply.payload === 'string' || typeof reply.payload === 'boolean' ||
      (typeof reply.payload === 'number' && Number.isFinite(reply.payload));
    if (!payloadValid) throw new TypeError('Invalid payload');
    seen.add(reply.requestId);
  }
  return requestIds.map((requestId, index) => ({
    requestId,
    payload: replies[index] ? replies[index].payload : null
  }));
}

module.exports = { alignReplies };
