'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['alignReplies']);
const { alignReplies } = api;
assert.equal(typeof alignReplies, 'function');

const requestIds = Object.freeze(['b', 'a', 'missing']);
const replies = Object.freeze([
  Object.freeze({ requestId: 'a', payload: 42 }),
  Object.freeze({ requestId: 'unrequested', payload: true }),
  Object.freeze({ requestId: 'b', payload: 'done' })
]);
const result = alignReplies(requestIds, replies);
assert.deepStrictEqual(result, [
  { requestId: 'b', payload: 'done' },
  { requestId: 'a', payload: 42 },
  { requestId: 'missing', payload: null }
]);
assert.deepStrictEqual(requestIds, ['b', 'a', 'missing']);
assert.deepStrictEqual(replies, [
  { requestId: 'a', payload: 42 },
  { requestId: 'unrequested', payload: true },
  { requestId: 'b', payload: 'done' }
]);
assert.deepStrictEqual(alignReplies([], []), []);
assert.deepStrictEqual(alignReplies(['x'], []), [{ requestId: 'x', payload: null }]);
assert.deepStrictEqual(
  alignReplies(['n', 's', 'b'], [
    { requestId: 'n', payload: null },
    { requestId: 's', payload: '' },
    { requestId: 'b', payload: false }
  ]),
  [
    { requestId: 'n', payload: null },
    { requestId: 's', payload: '' },
    { requestId: 'b', payload: false }
  ]
);

const again = alignReplies(requestIds, replies);
assert.notStrictEqual(again, result);
assert.notStrictEqual(again[0], result[0]);
result[0].payload = 'tampered';
result.push({ requestId: 'x', payload: null });
assert.deepStrictEqual(again[0], { requestId: 'b', payload: 'done' });

for (const args of [[null, []], [[], null], [{}, []], [[], {}]]) {
  assert.throws(() => alignReplies(...args), TypeError);
}
for (const ids of [[''], ['a', 'a'], ['a', 1], ['a', null]]) {
  assert.throws(() => alignReplies(ids, []), TypeError);
}
for (const badReplies of [
  [null], [[]], [{}],
  [{ requestId: 'a' }],
  [{ requestId: 'a', payload: null, extra: true }],
  [{ requestId: '', payload: null }],
  [{ requestId: 1, payload: null }],
  [{ requestId: 'a', payload: undefined }],
  [{ requestId: 'a', payload: NaN }],
  [{ requestId: 'a', payload: Infinity }],
  [{ requestId: 'a', payload: {} }],
  [{ requestId: 'a', payload: 1 }, { requestId: 'a', payload: 2 }]
]) assert.throws(() => alignReplies([], badReplies), TypeError);

